use std::{env,time::Instant};

fn mix64(mut x:u64)->u64{x=x.wrapping_add(0x9e3779b97f4a7c15);x=(x^(x>>30)).wrapping_mul(0xbf58476d1ce4e5b9);x=(x^(x>>27)).wrapping_mul(0x94d049bb133111eb);x^(x>>31)}
fn median(mut v:Vec<f64>)->f64{v.sort_by(|a,b|a.total_cmp(b));v[v.len()/2]}
fn emit(k:&str,u:u64,r:usize,s:f64,rate:f64,c:u64){println!("RESULT kernel={} units={} rounds={} seconds={:.9} rate={:.6} checksum={}",k,u,r,s,rate,c)}
fn c32(a:&[u32])->u64{let mut h=1469598103934665603u64;for(i,&x)in a.iter().enumerate(){h^=(x as u64).wrapping_add((i as u64).wrapping_mul(0x9e3779b1));h=h.wrapping_mul(1099511628211);}h}
fn c64(a:&[u64])->u64{let mut h=1469598103934665603u64;for(i,&x)in a.iter().enumerate(){h^=x.wrapping_add((i as u64).wrapping_mul(0x9e3779b97f4a7c15));h=h.wrapping_mul(1099511628211);}h}
fn timed<F:FnMut()->u64>(r:usize,mut f:F)->(f64,u64){let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let a=Instant::now();c=f();t.push(a.elapsed().as_secs_f64())}(median(t),c)}

fn integer50(n:u64)->u64{let mask=(1u64<<50)-1;let mut x=88172645463325252u64&mask;let mut s=0;for _ in 0..n{x^=x>>7;x^=(x<<8)&mask;x^=x>>9;x&=mask;s=s.wrapping_add(x^(x>>17))&mask}s}
fn bench_integer(n:u64,r:usize){let _=integer50(n/20+1);let(m,c)=timed(r,||integer50(n));emit("integer50",n,r,m,n as f64/m/1e6,c)}

const PAT:[u8;23]=[97,108,112,104,97,34,98,101,116,97,92,103,97,109,109,97,10,9,1,120,121,122,47];
fn json_escape(input:&[u8],out:&mut[u8])->usize{const H:&[u8;16]=b"0123456789abcdef";let mut j=0;out[j]=34;j+=1;for &c in input{match c{34=>{out[j]=92;out[j+1]=34;j+=2},92=>{out[j]=92;out[j+1]=92;j+=2},8=>{out[j]=92;out[j+1]=98;j+=2},12=>{out[j]=92;out[j+1]=102;j+=2},10=>{out[j]=92;out[j+1]=110;j+=2},13=>{out[j]=92;out[j+1]=114;j+=2},9=>{out[j]=92;out[j+1]=116;j+=2},0..=31=>{out[j]=92;out[j+1]=117;out[j+2]=48;out[j+3]=48;out[j+4]=H[(c>>4)as usize];out[j+5]=H[(c&15)as usize];j+=6},_=>{out[j]=c;j+=1}}}out[j]=34;j+1}
fn bench_json(n:u64,r:usize){let mut input=vec![0u8;n as usize];for i in 0..input.len(){input[i]=PAT[i%23]}let mut out=vec![0u8;n as usize*6+2];let _=json_escape(&input,&mut out);let mut on=0usize;let(m,_)=timed(r,||{on=json_escape(&input,&mut out);on as u64});let mut c=on as u64;for &x in &out[..on]{c+=x as u64}emit("json_escape",n,r,m,n as f64/m/1e9,c)}

fn merge_sort(a:&mut[u32],tmp:&mut[u32]){let n=a.len();let mut src_is_a=true;let mut w=1;while w<n{let(src,dst):(&[u32],&mut[u32])=if src_is_a{(&*a,&mut*tmp)}else{(&*tmp,&mut*a)};let mut lo=0;while lo<n{let mid=(lo+w).min(n);let hi=(lo+2*w).min(n);let(mut i,mut j,mut k)=(lo,mid,lo);while i<mid&&j<hi{if src[i]<=src[j]{dst[k]=src[i];i+=1}else{dst[k]=src[j];j+=1}k+=1}while i<mid{dst[k]=src[i];i+=1;k+=1}while j<hi{dst[k]=src[j];j+=1;k+=1}lo+=2*w}src_is_a=!src_is_a;if w>n/2{break}w*=2}if !src_is_a{a.copy_from_slice(tmp)}}
fn bench_merge(n:u64,r:usize){let n=n as usize;let base:(Vec<u32>)=(0..n).map(|i|mix64(i as u64)as u32).collect();let mut work=base.clone();let mut tmp=vec![0u32;n];merge_sort(&mut work,&mut tmp);let mut t=Vec::with_capacity(r);for _ in 0..r{work.copy_from_slice(&base);let a=Instant::now();merge_sort(&mut work,&mut tmp);t.push(a.elapsed().as_secs_f64())}let m=median(t);emit("merge_sort",n as u64,r,m,n as f64/m/1e6,c32(&work))}

fn bs(a:&[u32],x:u32)->i64{let(mut lo,mut hi)=(0usize,a.len());while lo<hi{let m=lo+(hi-lo)/2;if a[m]<x{lo=m+1}else{hi=m}}if lo<a.len()&&a[lo]==x{lo as i64}else{-1}}
fn bs_once(a:&[u32],q:u64)->u64{let mut h=0;for i in 0..q{let p=bs(a,(mix64(i)%(2*a.len()as u64))as u32);if p>=0{h+=p as u64+1}}h}
fn bench_bs(n:u64,r:usize){let a:Vec<u32>=(0..n).map(|i|(i*2)as u32).collect();let q=n*4;let _=bs_once(&a,q/20+1);let(m,c)=timed(r,||bs_once(&a,q));emit("binary_search",q,r,m,q as f64/m/1e6,c)}

fn prefix_once(input:&[u32],out:&mut[u64],passes:usize)->u64{let mut c=0;for p in 0..passes{let mut s=p as u64;for(i,&x)in input.iter().enumerate(){s+=x as u64;out[i]=s}c^=s}c}
fn bench_prefix(n:u64,r:usize){let input:Vec<u32>=(0..n).map(|i|(mix64(i)&1023)as u32).collect();let mut out=vec![0u64;n as usize];let _=prefix_once(&input,&mut out,1);let mut c=0;let mut t=Vec::with_capacity(r);for _ in 0..r{let a=Instant::now();c=prefix_once(&input,&mut out,16);t.push(a.elapsed().as_secs_f64())}c^=c64(&out);let m=median(t);emit("prefix_sum",n*16,r,m,n as f64*16.0/m/1e6,c)}

fn mm(a:&[u32],b:&[u32],c:&mut[u64],n:usize){for i in 0..n{for j in 0..n{let mut s=0u64;for k in 0..n{s+=(a[i*n+k]as u64)*(b[k*n+j]as u64)}c[i*n+j]=s}}}
fn bench_mm(n:u64,r:usize){let z=n as usize*n as usize;let a:Vec<u32>=(0..z).map(|i|(mix64(i as u64)&15)as u32).collect();let b:Vec<u32>=(0..z).map(|i|(mix64((i+z)as u64)&15)as u32).collect();let mut c=vec![0u64;z];mm(&a,&b,&mut c,n as usize);let mut t=Vec::with_capacity(r);for _ in 0..r{let q=Instant::now();mm(&a,&b,&mut c,n as usize);t.push(q.elapsed().as_secs_f64())}let m=median(t);emit("matrix_mul",n,r,m,(n as f64).powi(3)/m/1e6,c64(&c))}

fn graph(n:usize,d:usize,weights:bool)->(Vec<u32>,Vec<u32>){let mut a=vec![0u32;n*d];let mut w=if weights{vec![0u32;n*d]}else{vec![]};for i in 0..n{for e in 0..d{let p=i*d+e;let v=if e==0{(i+1)%n}else if e==1{(i+n-1)%n}else{(mix64((i*d+e)as u64)%n as u64)as usize};a[p]=v as u32;if weights{w[p]=(1+(mix64(0xabc00000+p as u64)&15))as u32}}}(a,w)}
fn bfs_once(a:&[u32],n:usize,d:usize,dist:&mut[i32],q:&mut[u32])->u64{dist.fill(-1);let(mut h,mut t)=(0usize,0usize);dist[0]=0;q[t]=0;t+=1;while h<t{let u=q[h]as usize;h+=1;let nd=dist[u]+1;for e in 0..d{let v=a[u*d+e]as usize;if dist[v]<0{dist[v]=nd;q[t]=v as u32;t+=1}}}let mut c=0u64;for i in 0..n{c+=((dist[i]+1)as u64)*(i as u64+1)}c}
fn bfs_many(a:&[u32],n:usize,d:usize,dist:&mut[i32],q:&mut[u32],p:usize)->u64{let mut h=0u64;for x in 0..p{h=h.wrapping_add(bfs_once(a,n,d,dist,q)^((x as u64).wrapping_mul(0x9e3779b97f4a7c15)))}h}
fn bench_bfs(n:u64,r:usize){let d=4;let(a,_)=graph(n as usize,d,false);let mut dist=vec![0i32;n as usize];let mut q=vec![0u32;n as usize];let _=bfs_many(&a,n as usize,d,&mut dist,&mut q,1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=bfs_many(&a,n as usize,d,&mut dist,&mut q,16);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("bfs",n*16,r,m,n as f64*d as f64*16.0/m/1e6,c)}

#[derive(Clone,Copy)]struct HP{d:u64,v:u32}
fn hp_push(h:&mut[HP],sz:&mut usize,x:HP){let mut i=*sz;*sz+=1;while i>0{let p=(i-1)/2;if h[p].d<=x.d{break}h[i]=h[p];i=p}h[i]=x}
fn hp_pop(h:&mut[HP],sz:&mut usize)->HP{let o=h[0];*sz-=1;let x=h[*sz];let mut i=0;loop{let l=i*2+1;if l>=*sz{break}let rr=l+1;let c=if rr<*sz&&h[rr].d<h[l].d{rr}else{l};if h[c].d>=x.d{break}h[i]=h[c];i=c}if *sz>0{h[i]=x}o}
fn dij_once(a:&[u32],w:&[u32],n:usize,d:usize,dist:&mut[u64],heap:&mut[HP])->u64{dist.fill(u64::MAX/4);let mut sz=0;dist[0]=0;hp_push(heap,&mut sz,HP{d:0,v:0});while sz>0{let x=hp_pop(heap,&mut sz);if x.d!=dist[x.v as usize]{continue}for e in 0..d{let p=x.v as usize*d+e;let v=a[p]as usize;let nd=x.d+w[p]as u64;if nd<dist[v]{dist[v]=nd;hp_push(heap,&mut sz,HP{d:nd,v:v as u32})}}}let mut c=0;for(i,&x)in dist.iter().enumerate(){c^=x.wrapping_add((i as u64).wrapping_mul(0x9e3779b97f4a7c15))}c}
fn bench_dij(n:u64,r:usize){let d=4;let(a,w)=graph(n as usize,d,true);let mut dist=vec![0u64;n as usize];let mut h=vec![HP{d:0,v:0};n as usize*d*4];let _=dij_once(&a,&w,n as usize,d,&mut dist,&mut h);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=dij_once(&a,&w,n as usize,d,&mut dist,&mut h);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("dijkstra",n,r,m,n as f64*d as f64/m/1e6,c)}

fn uf_find(p:&mut[u32],mut x:u32)->u32{while p[x as usize]!=x{p[x as usize]=p[p[x as usize]as usize];x=p[x as usize]}x}
fn uf_once(p:&mut[u32],rank:&mut[u8],n:usize,ops:u64)->u64{for i in 0..n{p[i]=i as u32;rank[i]=0}for i in 0..ops{let a=(mix64(i)%n as u64)as u32;let b=(mix64(i+ops)%n as u64)as u32;let(mut ra,mut rb)=(uf_find(p,a),uf_find(p,b));if ra!=rb{if rank[ra as usize]<rank[rb as usize]{std::mem::swap(&mut ra,&mut rb)}p[rb as usize]=ra;if rank[ra as usize]==rank[rb as usize]{rank[ra as usize]+=1}}}let mut h=0;for i in (0..n).step_by(17){h+=uf_find(p,i as u32)as u64}h}
fn bench_uf(n:u64,r:usize){let ops=n*4;let mut p=vec![0u32;n as usize];let mut rank=vec![0u8;n as usize];let _=uf_once(&mut p,&mut rank,n as usize,ops/20+1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=uf_once(&mut p,&mut rank,n as usize,ops);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("union_find",ops,r,m,ops as f64/m/1e6,c)}

fn mandel(w:usize,mi:usize)->u64{let mut sum=0;for y in 0..w{let ci=-1.5+3.0*y as f64/(w-1)as f64;for x in 0..w{let cr=-2.0+3.0*x as f64/(w-1)as f64;let(mut zr,mut zi,mut it)=(0.0,0.0,0);while it<mi{let(a,b)=(zr*zr,zi*zi);if a+b>4.0{break}let nz=a-b+cr;zi=2.0*zr*zi+ci;zr=nz;it+=1}sum+=it as u64}}sum}
fn bench_mandel(w:u64,r:usize){let _=mandel((w as usize).min(128),20);let(m,c)=timed(r,||mandel(w as usize,50));emit("mandelbrot",w*w,r,m,(w*w)as f64/m/1e6,c)}

fn va_once(n:usize)->u64{let mut v=Vec::<u64>::new();for i in 0..n{v.push(mix64(i as u64))}let mut h=0u64;for i in 0..n{v[i]^=i as u64;h=h.wrapping_add(v[i])}while let Some(x)=v.pop(){h^=x}h}
fn bench_va(n:u64,r:usize){let _=va_once(n as usize/20+1);let(m,c)=timed(r,||va_once(n as usize));emit("dynamic_array",n,r,m,n as f64/m/1e6,c)}

fn ll_once(next:&mut[u32],val:&mut[u64],n:usize,passes:usize)->u64{for i in 0..n{next[i]=if i+1<n{(i+1)as u32}else{u32::MAX};val[i]=mix64(i as u64)}let b=64;let mut base=0;while base<n{let hi=(base+b).min(n)-1;for i in base..=hi{next[i]=if i==base{if hi+1<n{(hi+1)as u32}else{u32::MAX}}else{(i-1)as u32}}base+=b}let mut h=0u64;for p in 0..passes{let mut cur=if b<n{(b-1)as u32}else{(n-1)as u32};let mut seen=0usize;while cur!=u32::MAX&&seen<n{let u=cur as usize;val[u]^=(seen+p)as u64;h=h.wrapping_add(val[u]);cur=next[u];seen+=1}h^=seen as u64}h}
fn bench_ll(n:u64,r:usize){let mut next=vec![0u32;n as usize];let mut val=vec![0u64;n as usize];let _=ll_once(&mut next,&mut val,n as usize,1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=ll_once(&mut next,&mut val,n as usize,16);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("linked_list",n*16,r,m,n as f64*16.0/m/1e6,c)}

fn qr_once(b:&mut[u64],ops:u64)->u64{let cap=b.len();let(mut h,mut t,mut cnt)=(0usize,0usize,0usize);let mut z=0u64;for i in 0..ops{if i&3!=3{if cnt==cap{z^=b[h];h=(h+1)%cap;cnt-=1}b[t]=mix64(i);t=(t+1)%cap;cnt+=1}else if cnt>0{let x=b[h];h=(h+1)%cap;cnt-=1;z=z.wrapping_add(x)}}while cnt>0{z^=b[h];h=(h+1)%cap;cnt-=1}z}
fn bench_qr(ops:u64,r:usize){let mut b=vec![0u64;ops as usize/2+1024];let _=qr_once(&mut b,ops/20+1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=qr_once(&mut b,ops);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("queue_ring",ops,r,m,ops as f64/m/1e6,c)}

fn np2(mut x:usize)->usize{let mut p=1;while p<x{p<<=1}p}
fn ht_once(keys:&mut[u64],vals:&mut[u64],n:usize)->u64{keys.fill(0);let mask=keys.len()-1;let mut h=0u64;for i in 0..n{let k=mix64(i as u64)|1;let v=mix64(i as u64+0x55555555);let mut p=mix64(k)as usize&mask;while keys[p]!=0&&keys[p]!=k{p=(p+1)&mask}keys[p]=k;vals[p]=v}for i in 0..n{let k=mix64(i as u64)|1;let mut p=mix64(k)as usize&mask;while keys[p]!=k{p=(p+1)&mask}vals[p]^=i as u64;h=h.wrapping_add(vals[p])}h}
fn bench_ht(n:u64,r:usize){let cap=np2(n as usize*2);let mut k=vec![0u64;cap];let mut v=vec![0u64;cap];let _=ht_once(&mut k,&mut v,n as usize/20+1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=ht_once(&mut k,&mut v,n as usize);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("hash_table",n,r,m,n as f64*2.0/m/1e6,c)}

fn bhpush(h:&mut[u64],sz:&mut usize,x:u64){let mut i=*sz;*sz+=1;while i>0{let p=(i-1)/2;if h[p]<=x{break}h[i]=h[p];i=p}h[i]=x}
fn bhpop(h:&mut[u64],sz:&mut usize)->u64{let o=h[0];*sz-=1;let x=h[*sz];let mut i=0;loop{let l=i*2+1;if l>=*sz{break}let rr=l+1;let c=if rr<*sz&&h[rr]<h[l]{rr}else{l};if h[c]>=x{break}h[i]=h[c];i=c}if *sz>0{h[i]=x}o}
fn bh_once(h:&mut[u64],n:usize)->u64{let mut sz=0;for i in 0..n{bhpush(h,&mut sz,mix64(i as u64))}let mut c=0;for i in 0..n{c^=bhpop(h,&mut sz).wrapping_add(i as u64)}c}
fn bench_bh(n:u64,r:usize){let mut h=vec![0u64;n as usize];let _=bh_once(&mut h,n as usize/20+1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=bh_once(&mut h,n as usize);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("binary_heap",n,r,m,n as f64*2.0/m/1e6,c)}

fn bst_once(keys:&mut[u64],left:&mut[i32],right:&mut[i32],n:usize)->u64{let mut root=-1i32;for i in 0..n{let k=mix64(i as u64);keys[i]=k;left[i]=-1;right[i]=-1;let node=i as i32;if root<0{root=node;continue}let mut cur=root;loop{let u=cur as usize;if k<keys[u]{if left[u]<0{left[u]=node;break}cur=left[u]}else{if right[u]<0{right[u]=node;break}cur=right[u]}}}let mut h=0;for i in (0..n).step_by(3){let k=mix64(i as u64);let mut cur=root;while cur>=0&&keys[cur as usize]!=k{let u=cur as usize;cur=if k<keys[u]{left[u]}else{right[u]}}if cur>=0{h+=cur as u64+1}}h}
fn bench_bst(n:u64,r:usize){let mut k=vec![0u64;n as usize];let mut l=vec![0i32;n as usize];let mut rr=vec![0i32;n as usize];let _=bst_once(&mut k,&mut l,&mut rr,n as usize/20+1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=bst_once(&mut k,&mut l,&mut rr,n as usize);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("bst",n,r,m,n as f64/m/1e6,c)}

fn trie_once(ch:&mut[i32],term:&mut[u8],words:usize,passes:usize)->u64{ch.fill(-1);term.fill(0);let mut used=1usize;for i in 0..words{let w=mix64(i as u64)as u32;let mut node=0usize;for sh in (0..=28).rev().step_by(4){let c=((w>>sh)&15)as usize;let p=node*16+c;if ch[p]<0{ch[p]=used as i32;used+=1}node=ch[p]as usize}term[node]=1}let mut h=used as u64;for p in 0..passes{for i in (0..words).step_by(2){let w=mix64(i as u64)as u32;let mut node=0i32;for sh in (0..=28).rev().step_by(4){if node<0{break}node=ch[node as usize*16+((w>>sh)&15)as usize]}if node>=0&&term[node as usize]!=0{h=h.wrapping_add(node as u64+1+p as u64)}}}h}
fn bench_trie(n:u64,r:usize){let mx=1+n as usize*8;let mut ch=vec![-1i32;mx*16];let mut term=vec![0u8;mx];let _=trie_once(&mut ch,&mut term,n as usize/20+1,1);let mut t=Vec::with_capacity(r);let mut c=0;for _ in 0..r{let s=Instant::now();c=trie_once(&mut ch,&mut term,n as usize,32);t.push(s.elapsed().as_secs_f64())}let m=median(t);emit("trie",n*32,r,m,n as f64*32.0/m/1e6,c)}

fn size(k:&str)->u64{match k{"integer50"=>200000000,"json_escape"=>16000000,"merge_sort"=>1000000,"binary_search"=>1000000,"prefix_sum"=>8000000,"matrix_mul"=>320,"bfs"=>200000,"dijkstra"=>100000,"union_find"=>1000000,"mandelbrot"=>1600,"dynamic_array"=>5000000,"linked_list"=>4000000,"queue_ring"=>10000000,"hash_table"=>1000000,"binary_heap"=>1000000,"bst"=>300000,"trie"=>100000,_=>0}}
fn main(){let a:Vec<String>=env::args().collect();let k=a.get(1).map(String::as_str).unwrap_or("integer50");let n=a.get(2).and_then(|x|x.parse().ok()).unwrap_or_else(||size(k));let r=a.get(3).and_then(|x|x.parse().ok()).unwrap_or(7usize);match k{"integer50"=>bench_integer(n,r),"json_escape"=>bench_json(n,r),"merge_sort"=>bench_merge(n,r),"binary_search"=>bench_bs(n,r),"prefix_sum"=>bench_prefix(n,r),"matrix_mul"=>bench_mm(n,r),"bfs"=>bench_bfs(n,r),"dijkstra"=>bench_dij(n,r),"union_find"=>bench_uf(n,r),"mandelbrot"=>bench_mandel(n,r),"dynamic_array"=>bench_va(n,r),"linked_list"=>bench_ll(n,r),"queue_ring"=>bench_qr(n,r),"hash_table"=>bench_ht(n,r),"binary_heap"=>bench_bh(n,r),"bst"=>bench_bst(n,r),"trie"=>bench_trie(n,r),_=>panic!("unknown kernel")}}
